window.AUTH=window.AUTH||{};window.AUTH["23-861"]={"d":"23-861","id":"2024/23-861","n":"Feliciano v. Department of Transportation","briefs":[{"k":"petitioner","label":"Brief of petitioner Nick Feliciano","date":"2024-08-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-861/322750/20240819120606869_Feliciano%20-%20Merits%20Brief%20and%20Statutory%20Addendum%20Combined%20-%20RTF.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondent Department of Transportation","date":"2024-09-27","url":"https://www.supremecourt.gov/DocketPDF/23/23-861/327080/20240927183706485_23-861bsUnitedStates_f.pdf","side":"res","n":91},{"k":"reply","label":"Reply of petitioner Nick Feliciano","date":"2024-10-28","url":"https://www.supremecourt.gov/DocketPDF/23/23-861/330433/20241028144938898_Feliciano%20--%20Merits%20Reply%20--%20Final.pdf","side":"pet","n":16}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us1r29_bp7c.pdf","tr":true,"items":[{"t":"case","label":"Adams v. Department of Homeland Security","cite":"3 F.4th 1375","y":2021,"url":"https://www.courtlistener.com/c/F.4th/3/1375/","by":{"0":"6, 9","1":"8, 25","2":"1, 2, 12, 18"},"q":[{"src":"brief","b":0,"text":"voluntary duty that was unconnected to the emergency at hand.","cite":"3 F.4th at 1380"},{"src":"brief","b":0,"text":"involve a connection to the declared national emergency.","cite":"3 F.4th at 1380"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"directly called to serve in a contingency operation,","cite":"3 F. 4th 1375, 1379"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"orders stat[ing] that they are `non-contingency' activation orders.","cite":"3 F. 4th, at 1377"}]},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"by":{"0":"18, 19, 26","1":"34"},"q":[{"src":"brief","b":0,"text":"that a given term is used to mean the same thing throughout a statute, a presumption surely at its most vigorous when a term is repeated within a given sentence.","cite":"513 U.S. 115, 118"}]},{"t":"case","label":"Colicelli v. Dep’t of Veterans Affs.","cite":"2020 WL 1915737","y":2020,"court":"M.S.P.B. Apr. 14","by":{"0":"6"}},{"t":"case","label":"Conn. Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"0":"14"}},{"t":"case","label":"Del Colle v. DOJ","cite":"2021 WL 1377041","y":2021,"court":"M.S.P.B. Apr. 8","by":{"0":"5"}},{"t":"case","label":"Doe v. Dep’t of State","cite":"2016 WL 5919634","y":2016,"court":"M.S.P.B. Oct. 6","by":{"0":"6"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"25","1":"34"},"q":[{"src":"brief","b":0,"text":"ha[s] long applied ‘the canon that provisions for benefits to members of the Armed Services are to be construed in the beneficiaries’ favor.’","cite":"562 U.S. 428, 441"}]},{"t":"case","label":"King v. Burwell","cite":"576 U.S. 473","y":2015,"id":"2014/14-114","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"[a] fair reading of legislation demands a fair understanding of the legislative plan.","cite":"576 U.S. 473, 498"}]},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"by":{"0":"25"}},{"t":"case","label":"Kloeckner v. Solis","cite":"568 U.S. 41","y":2012,"id":"2012/11-184","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"even the most formidable argument concerning the statute’s purposes could not overcome","cite":"568 U.S. 41, 55 n.4"}]},{"t":"case","label":"Marquiz v. Dep’t of Def.","cite":"2015 WL 1187022","y":2015,"court":"M.S.P.B. Mar. 12","by":{"0":"6"},"q":[{"src":"argument","who":"Ms. Reaves","text":"There's a 2016 decision called Marquiz, where the Board as a whole divided on this question. ALJs have come out different ways. So Petitioner in his cert stage papers cited some examples of individual ALJ judges coming out his direction."}]},{"t":"case","label":"Maslenjak v. United States","cite":"582 U.S. 335","y":2017,"id":"2016/16-309","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"‘to make sense rather than nonsense out of the corpus juris.’","cite":"582 U.S. 335, 345"}]},{"t":"case","label":"(iii) Cases—Continued Miller v. Dep’t of Treasury","cite":"2016 WL 6406552","y":2016,"court":"M.S.P.B. Oct. 24","by":{"0":"6"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"by":{"0":"16","1":"27"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"the best evidence of Congress’s intent is the statutory text,","cite":"567 U.S. 519, 544"}]},{"t":"case","label":"Nicewicz v. Dep’t of Navy","cite":"2019 WL 438258","y":2019,"court":"M.S.P.B. Jan. 31","by":{"0":"6"}},{"t":"case","label":"Robinson v. Dep’t of Veteran Affs.","cite":"2021 WL 1961624","y":2021,"court":"M.S.P.B. May 12","by":{"0":"5"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"by":{"0":"14, 16"},"q":[{"src":"brief","b":0,"text":"[i]f the words of a statute are unambiguous, this first step of the interpretive inquiry is [the] last.","cite":"589 U.S. 8, 13"}]},{"t":"case","label":"Rudisill v. McDonough","cite":"601 U.S. 294","y":2024,"id":"2023/22-888","sc":1,"by":{"0":"25","1":"34, 35"},"q":[{"src":"brief","b":0,"text":"ambiguous, the pro-veteran canon would favor","cite":"601 U.S. 294, 314"},{"src":"brief","b":1,"text":"apparently * * * not affected the result * * * in any of this Court’s past decisions in veterans cases,","cite":"601 U.S. at 316"}]},{"t":"case","label":"Santiago v. Dep’t of Veterans Affs.","cite":"2021 WL 1171023","y":2021,"court":"M.S.P.B. Mar. 22","by":{"0":"5"}},{"t":"case","label":"Smith v. United States","cite":"508 U.S. 223","y":1993,"id":"1992/91-8674","sc":1,"by":{"0":"16","1":"27"}},{"t":"case","label":"Sutton v. United Air Lines","cite":"527 U.S. 471","y":1999,"id":"1998/97-1943","sc":1,"by":{"0":"23"}},{"t":"case","label":"United Sav. Assn. of Tex. v. Timbers of Inwood Forest Associates, Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"[a] provision that may seem ambiguous in isolation is often clarified by the remainder of the statutory scheme * * * because only one of the permissible meanings produces a substantive effect that is compatible with the rest of the law.","cite":"484 U.S. 365, 371"}]},{"t":"case","label":"United States v. Ressam","cite":"553 U.S. 272","y":2008,"id":"2007/07-455","sc":1,"by":{"0":"2, 3, 10, 11, 13, 15, 16, 21, 22, 26, 16, 13, 14, 22","1":"11, 14, 26","2":"3, 5, 4"},"q":[{"src":"brief","b":0,"text":"The term ‘during’ denotes a temporal link; that is surely the most natural reading of the word.","cite":"553 U.S. 272, 274"},{"src":"brief","b":0,"text":"[t]he term ‘during’ denotes a temporal link; that is surely the most natural reading of the word.","cite":"553 U.S. at 274"},{"src":"brief","b":1,"text":"[t]he term ‘during’ denotes a temporal link; that is surely the most natural reading of the word as used in th[at] statute.","cite":"553 U.S. at 274"},{"src":"brief","b":2,"text":"is surely [its] most natural reading.","cite":"553 U.S. 272, 274"},{"src":"brief","b":2,"text":"[i]t does not normally mean ‘at the same time and in connection with.’","cite":"553 U.S. 272"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"that word `denotes a temporal link' and means `contemporaneous with.'","cite":"553 U. S., at 274"},{"src":"argument","who":"Mr. Tutt","text":"The government resists this common-sense temporal definition of \"during,\" the same definition it argued for in Ressam. Instead, the government says \"during\" here means \"in the course of,\" and \"in the course of,\" it says, requires a substantive connection between a reservist's military service and a pending national emergency."},{"src":"argument","who":"Mr. Tutt","text":"I mean, the Court didn't think it was very flexible at all in Ressam, where you said that carrying explosive during the -- during the commission of any felony means you get a 10-year enhancement."}]},{"t":"case","label":"United States v. Rosenberg","cite":"806 F.2d 1169","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/806/1169/","by":{"0":"16","2":"4"}},{"t":"case","label":"W. Va. Univ. Hosps., Inc. v. Casey","cite":"499 U.S. 83","y":1991,"id":"1990/89-994","sc":1,"by":{"0":"22"}},{"t":"case","label":"Woods v. Dep’t of Veteran Affs.","cite":"2019 WL 1315856","y":2019,"court":"M.S.P.B. Mar. 21","by":{"0":"6"}},{"t":"case","label":"Ysleta Del Sur Pueblo v. Texas","cite":"596 U.S. 685","y":2022,"id":"2021/20-493","sc":1,"by":{"0":"21"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"[i]t is not our place to question whether Congress adopted the . . . most workable policy, only to discern and apply the policy it did adopt.","cite":"596 U. S. 685, 706"}]},{"t":"usc","label":"5 U.S.C. § 5538","url":"https://www.law.cornell.edu/uscode/text/5/5538","subs":["(a)","(a)(2)","(c)(1)","(c)(3)","(d)","(e)(2)"],"stext":{"head":"§5538. Nonreduction in pay while serving in the uniformed services or National Guard","paras":[[0,"(a) An employee who is absent from a position of employment with the Federal Government in order to perform active duty in the uniformed services pursuant to a call or order to active duty under section 12304b of title 10 or a provision of law referred to in section 101(a)(13)(B) of title 10 shall be entitled, while serving on active duty, to receive, for each pay period described in subsection (b), an amount equal to the amount by which—"],[1,"(1) the amount of basic pay which would otherwise have been payable to such employee for such pay period if such employee's civilian employment with the Government had not been interrupted by that service, exceeds (if at all)"],[1,"(2) the amount of pay and allowances which (as determined under subsection (d))—"],[2,"(A) is payable to such employee for that service; and"],[2,"(B) is allocable to such pay period."],[0,"(b) Amounts under this section shall be payable with respect to each pay period (which would otherwise apply if the employee's civilian employment had not been interrupted)—"],[1,"(1) during which such employee is entitled to re-employment rights under chapter 43 of title 38 with respect to the position from which such employee is absent (as referred to in subsection (a)); and"],[1,"(2) for which such employee does not otherwise receive basic pay (including by taking any annual, military, or other paid leave) to which such employee is entitled by virtue of such employee's civilian employment with the Government."],[0,"(c) Any amount payable under this section to an employee shall be paid—"],[1,"(1) by such employee's employing agency;"],[1,"(2) from the appropriation or fund which would be used to pay the employee if such employee were in a pay status; and"],[1,"(3) to the extent practicable, at the same time and in the same manner as would basic pay if such employee's civilian employment had not been interrupted."],[0,"(d) The Office of Personnel Management shall, in consultation with Secretary of Defense, prescribe any regulations necessary to carry out the preceding provisions of this section."],[0,"(e)(1) The head of each agency referred to in section 2302(a)(2)(C)(ii) shall, in consultation with the Office, prescribe procedures to ensure that the rights under this section apply to the employees of such agency."],[0,"(2) The Administrator of the Federal Aviation Administration shall, in consultation with the Office, prescribe procedures to ensure that the rights under this section apply to the employees of that agency."],[0,"(f) For purposes of this section—"],[1,"(1) the terms \"employee\", \"Federal Government\", and \"uniformed services\" have the same respective meanings as given those terms in section 4303 of title 38;"],[1,"(2) the term \"employing agency\", as used with respect to an employee entitled to any payments under this section, means the agency or other entity of the Government (including an agency referred to in section 2302(a)(2)(C)(ii)) with respect to which such employee has reemployment rights under chapter 43 of title 38; and"],[1,"(3) the term \"basic pay\" includes any amount payable under section 5304."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/5538?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2","1":"9, 9, 9, 9, 9, 9, 9, 3, 25, 29","2":"10, 12, 15"},"q":[{"src":"brief","b":0,"text":"order[ed] to perform active duty in the uniformed services pursuant to a call or order to active duty under * * * a provision of law referred to in section 101(a)(13)(B) of title 10.","cite":"5 U.S.C. § 5538(a)"},{"src":"brief","b":0,"text":"perform active duty * * * pursuant to a call or order to active duty under * * * a provision of law referred to in section 101(a)(13)(B) of title 10.","cite":"5 U.S.C. § 5538(a)"},{"src":"brief","b":1,"text":"order[ed] to perform active duty in the uniformed services pursuant to a call or order to active duty under * * * a provision of law referred to in section 101(a)(13)(B) of title 10.","cite":"5 U.S.C. 5538(a)"},{"src":"brief","b":1,"text":"prescrib[ing] any regulations necessary to carry out","cite":"5 U.S.C. 5538(d)"},{"src":"brief","b":2,"text":"call[ed] or order[ed] to active duty under * * * a provision of law referred to in [10 U.S.C.] section 101(a)(13)(B).","cite":"5 U.S.C. § 5538(a)"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"a military operation that . . . is designated by the Secretary of Defense as an operation in which members of the armed forces are or may become involved in military actions, operations, or hostilities against an enemy of the United States or against an opposing military force.","cite":"5 U. S. C. § 5538(a)"},{"src":"argument","who":"Ms. Reaves","text":"And I think you're completely right that there is a textual hook for that both in Section 5538 and in Section 101(a)(13)(B). Both refer to the call or order to active duty."},{"src":"argument","who":"Ms. Reaves","text":"You know, I'm not -- I -- I can't say that in the legislative history that I've looked at for Section 5538 there was discussion or that much focus on the orders."}]},{"t":"usc","label":"7 U.S.C. § 4208","url":"https://www.law.cornell.edu/uscode/text/7/4208","subs":["(b)"],"by":{"0":"21"}},{"t":"usc","label":"8 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/8/1324","subs":["(a)(1)(B)(iii)"],"by":{"0":"21"}},{"t":"usc","label":"10 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/10/101","subs":["(a)(13)(B)","(a)(13)(A)","(d)(1)"],"stext":{"head":"§101. Definitions","paras":[[0,"(a) In General.—The following definitions apply in this title:"],[1,"(1) The term \"United States\", in a geographic sense, means the States and the District of Columbia."],[1,"[(2) Repealed. Pub. L. 109–163, div. A, title X, §1057(a)(1), Jan. 6, 2006, 119 Stat. 3440.]"],[1,"(3) The term \"possessions\" includes the Virgin Islands, Guam, American Samoa, and the Guano Islands, so long as they remain possessions, but does not include any Commonwealth."],[1,"(4) The term \"armed forces\" means the Army, Navy, Air Force, Marine Corps, Space Force, and Coast Guard."],[1,"(5) The term \"uniformed services\" means—"],[2,"(A) the armed forces;"],[2,"(B) the commissioned corps of the National Oceanic and Atmospheric Administration; and"],[2,"(C) the commissioned corps of the Public Health Service."],[1,"(6) The term \"department\", when used with respect to a military department, means the executive part of the department and all field headquarters, forces, reserve components, installations, activities, and functions under the control or supervision of the Secretary of the department. When used with respect to the Department of Defense, such term means the executive part of the department, including the executive parts of the military departments, and all field headquarters, forces, reserve components, installations, activities, and functions under the control or supervision of the Secretary of Defense, including those of the military departments."],[1,"(7) The term \"executive part of the department\" means the executive part of the Department of Defense, Department of the Army, Department of the Navy, or Department of the Air Force, as the case may be, at the seat of government."],[1,"(8) The term \"military departments\" means the Department of the Army, the Department of the Navy, and the Department of the Air Force."],[1,"(9) The term \"Secretary concerned\" means—"],[2,"(A) the Secretary of the Army, with respect to matters concerning the Army;"],[2,"(B) the Secretary of the Navy, with respect to matters concerning the Navy, the Marine Corps, and the Coast Guard when it is operating as a service in the Department of the Navy;"],[2,"(C) the Secretary of the Air Force, with respect to matters concerning the Air Force and the Space Force; and"],[2,"(D) the Secretary of Homeland Security, with respect to matters concerning the Coast Guard when it is not operating as a service in the Department of the Navy."],[1,"(10) The term \"service acquisition executive\" means the civilian official within a military department who is designated as the service acquisition executive for purposes of regulations and procedures providing for a service acquisition executive for that military department."],[1,"(11) The term \"Defense Agency\" means an organizational entity of the Department of Defense—"],[2,"(A) that is established by the Secretary of Defense under section 191 of this title (or under the second sentence of section 125(d) of this title (as in effect before October 1, 1986)) to perform a supply or service activity common to more than one military department (other than such an entity that is designated by the Secretary as a Department of Defense Field Activity); or"],[2,"(B) that is designated by the Secretary of Defense as a Defense Agency."],[1,"(12) The term \"Department of Defense Field Activity\" means an organizational entity of the Department of Defense—"],[2,"(A) that is established by the Secretary of Defense under section 191 of this title (or under the second sentence of section 125(d) of this title (as in effect before October 1, 1986)) to perform a supply or service activity common to more than one military department; and"],[2,"(B) that is designated by the Secretary of Defense as a Department of Defense Field Activity."],[1,"(13) The term \"contingency operation\" means a military operation that—"],[2,"(A) is designated by the Secretary of Defense as an operation in which members of the armed forces are or may become involved in military actions, operations, or hostilities against an enemy of the United States or against an opposing military force; or"],[2,"(B) results in the call or order to, or retention on, active duty of members of the uniformed services under section 688, 12301(a), 12302, 12304, 12304a, 12305, or 12406 of this title, chapter 13 of this title, section 3713 of title 14, or any other provision of law during a war or during a national emergency declared by the President or Congress."],[1,"(14) The term \"supplies\" includes material, equipment, and stores of all kinds."],[1,"(15) The term \"pay\" includes basic pay, special pay, retainer pay, incentive pay, retired pay, and equivalent pay, but does not include allowances."],[1,"(16) The term \"congressional defense committees\" means—"],[2,"(A) the Committee on Armed Services and the Committee on Appropriations of the Senate; and"],[2,"(B) the Committee on Armed Services and the Committee on Appropriations of the House of Representatives."],[1,"(17) The term \"base closure law\" means the following:"],[2,"(A) Section 2687 of this title."],[2,"(B) The Defense Base Closure and Realignment Act of 1990 (part A of title XXIX of Public Law 101–510; 10 U.S.C. 2687 note)."],[2,"(C) Title II of the Defense Authorization Amendments and Base Closure and Realignment Act (Public Law 100–526; 10 U.S.C. 2687 note)."],[1,"(18) The term \"acquisition workforce\" means the persons serving in acquisition positions within the Department of Defense, as designated pursuant to section 1721(a) of this title."],[1,"(19) The term \"climate resilience\" means the capability to avoid, prepare for, minimize the effect of, adapt to, and recover from, extreme weather, or from anticipated or unanticipated changes in environmental conditions, that do (or have the potential to) adversely affect the national security of the United States or of allies and partners of the United States."],[1,"(20) The term \"extreme weather\" means recurrent flooding, drought, desertification, wildfires, thawing permafrost, sea level fluctuation, changes in mean high tides, or any other weather-related event, or anticipated change in environmental conditions, that present (or are projected to present) a recurring annual threat to the climate security of the United States or of allies and partners of the United States."],[0,"(b) Personnel Generally.—The following definitions relating to military personnel apply in this title:"],[1,"(1) The term \"officer\" means a commissioned or warrant officer."],[1,"(2) The term \"commissioned officer\" includes a commissioned warrant officer."],[1,"(3) The term \"warrant officer\" means a person who holds a commission or warrant in a warrant officer grade."],[1,"(4) The term \"general officer\" means an officer of the Army, Air Force, Marine Corps, or Space Force serving in or having the grade of general, lieutenant general, major general, or brigadier general."],[1,"(5) The term \"flag officer\" means an officer of the Navy or Coast Guard serving in or having the grade of admiral, vice admiral, rear admiral, or rear admiral (lower half)."],[1,"(6) The term \"enlisted member\" means a person in an enlisted grade."],[1,"(7) The term \"grade\" means a step or degree, in a graduated scale of office or military rank, that is established and designated as a grade by law or regulation."],[1,"(8) The term \"rank\" means the order of precedence among members of the armed forces."],[1,"(9) The term \"rating\" means the name (such as \"boatswain's mate\") prescribed for members of an armed force in an occupational field. The term \"rate\" means the name (such as \"chief boatswain's mate\") prescribed for members in the same rating or other category who are in the same grade (such as chief petty officer or seaman apprentice)."],[1,"(10) The term \"original\", with respect to the appointment of a member of the armed forces in a regular or reserve component, refers to that member's most recent appointment in that component that is neither a promotion nor a demotion and, with respect to the appointment of a member of the armed forces in the Space Force, refers to that member's most recent appointment in the Space Force that is neither a promotion nor a demotion."],[1,"(11) The term \"authorized strength\" means the largest number of members authorized to be in an armed force, a component, a branch, a grade, or any other category of the armed forces."],[1,"(12) The term \"regular\", with respect to an enlistment, appointment, grade, or office, means enlistment, appointment, grade, or office in a regular component of an armed force."],[1,"(13) The term \"active-duty list\" means a single list for the Army, Navy, Air Force, Marine Corps, or Space Force (required to be maintained under section 620 of this title) which contains the names of all officers of that armed force, other than officers described in section 641 of this title, who are serving on active duty."],[1,"(14) The term \"medical officer\" means an officer of the Medical Corps of the Army, an officer of the Medical Corps of the Navy, or an officer in the Air Force designated as a medical officer."],[1,"(15) The term \"dental officer\" means an officer of the Dental Corps of the Army, an officer of the Dental Corps of the Navy, or an officer of the Air Force designated as a dental officer."],[1,"(16) The term \"Active Guard and Reserve\" means a member of a reserve component who is on active duty pursuant to section 12301(d) of this title or, if a member of the Army National Guard or Air National Guard, is on full-time National Guard duty pursuant to section 502(f) of title 32, and who is performing Active Guard and Reserve duty."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 5, 6, 8, 9, 10, 14, 15, 17, 20, 24, 25, 26","1":"3, 3, 3, 3","2":"1, 3, 10, 11, 12, 13, 15"},"q":[{"src":"brief","b":0,"text":"any other provision of law during a war or during a national emergency declared by the President or Congress.","cite":"10 U.S.C. § 101(a)(13)(B)"},{"src":"brief","b":0,"text":"section 688, 12301(a), 12302, 12304, 12304a, 12305, or 12406 of [title 10], chapter 13 of [title 10], section 3713 of title 14, or any other provision of law during a war or during a national emergency declared by the President or Congress.","cite":"10 U.S.C. § 101(a)(13)(B)"},{"src":"brief","b":1,"text":"members of the armed forces are or may become involved in military actions, operations, or hostilities against an enemy of the United States or against an opposing military force.","cite":"10 U.S.C. 101(a)(13)(A)"},{"src":"brief","b":1,"text":"does not include full-time National Guard duty.","cite":"10 U.S.C. 101(d)(1)"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"on active duty pursuant to a call or order to active duty under a provision of law referred to","cite":"10 U. S. C. § 101(a)(13)"}]},{"t":"usc","label":"14 U.S.C. § 331","url":"https://www.law.cornell.edu/uscode/text/14/331","by":{"0":"20"}},{"t":"usc","label":"14 U.S.C. § 367","url":"https://www.law.cornell.edu/uscode/text/14/367","subs":["(3)"],"by":{"0":"20"}},{"t":"usc","label":"18 U.S.C. § 115","url":"https://www.law.cornell.edu/uscode/text/18/115","subs":["(b)(1)(B)(iv)"],"by":{"0":"21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"38 U.S.C. § 4312","url":"https://www.law.cornell.edu/uscode/text/38/4312","subs":["(c)(4)(B)"],"by":{"0":"8"}},{"t":"usc","label":"50 U.S.C. § 1435","url":"https://www.law.cornell.edu/uscode/text/50/1435","stext":{"head":"§1435. Effective period","paras":[[0,"This chapter shall be effective only during a national emergency declared by Congress or the President and for six months after the termination thereof or until such earlier time as Congress, by concurrent resolution, may designate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/50/1435?type=usc&year=mostrecent&link-type=html"},"by":{"0":"19","1":"30","2":"7, 14"},"q":[{"src":"brief","b":1,"text":"for six months after the termination thereof.","cite":"50 U.S.C. 1435"}]},{"t":"law","label":"Pub. L. No. 115-232","url":"https://www.govinfo.gov/link/plaw/115/public/232","by":{"0":"20","1":"6"}},{"t":"law","label":"Pub. L. No. 118-31","url":"https://www.govinfo.gov/link/plaw/118/public/31","by":{"0":"20"}},{"t":"law","label":"Pub. L. No. 94-412","url":"https://www.govinfo.gov/link/statute/90/1255","by":{"0":"20, 21"}},{"t":"reg","label":"Executive Order No. 13223, 66 Fed. Reg. 48,201","url":"https://www.govinfo.gov/link/fr/66/48201","by":{"0":"8","1":"7"}},{"t":"case","label":"Advocate Health Care Network v. Stapleton","cite":"581 U.S. 468","y":2017,"id":"2016/16-74","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"Congress did not in fact want what [petitioner] claim[s].","cite":"581 U.S. 468, 477"}]},{"t":"case","label":"American Nat’l Red Cross v. S.G.","cite":"505 U.S. 247","y":1992,"id":"1991/91-594","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"be read, if possible, to have some effect.","cite":"505 U.S. 247, 263"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"a change in [statutory] language . . . , if possible, to have some effect.","cite":"505 U. S. 247, 263"}]},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"by":{"1":"33"}},{"t":"case","label":"Department of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"by":{"1":"27","2":"12"},"q":[{"src":"brief","b":1,"text":"hardly means it was ‘foreclosed . . . from using different language to accomplish the same goal’","cite":"601 U.S. 42, 52"}]},{"t":"case","label":"DeVillier v. Texas","cite":"601 U.S. 285","y":2024,"id":"2023/22-913","sc":1,"by":{"1":"15"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"588 U.S. 427","y":2019,"id":"2018/18-481","sc":1,"by":{"1":"31"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"by":{"1":"38"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"by":{"1":"17"}},{"t":"case","label":"Lindke v. Freed","cite":"601 U.S. 187","y":2024,"id":"2023/22-611","sc":1,"by":{"1":"15"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"1":"20"}},{"t":"case","label":"McIntosh v. United States","cite":"601 U.S. 330","y":2024,"id":"2023/22-7386","sc":1,"by":{"1":"15"}},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"hardships are to be remedied by payment of Government funds, it must be at the instance of Congress.","cite":"496 U.S. 414, 434"}]},{"t":"case","label":"Pavelic & LeFlore v. Marvel Entm’t Grp.","cite":"493 U.S. 120","y":1989,"id":"1989/88-791","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"apply the text, not to improve upon it.","cite":"493 U.S. 120, 126"}]},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"by":{"1":"16"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"[i]n a given statute, the same term usually has the same meaning and different terms usually have different meanings.","cite":"601 U. S. 124, 149"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"likely to keep track of and standardize.","cite":"601 U. S., at 149"}]},{"t":"case","label":"Sackett v. EPA","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"by":{"1":"17"}},{"t":"case","label":"United States Fish & Wildlife Serv. v. Sierra Club, Inc.","cite":"592 U.S. 261","y":2021,"url":"https://supreme.justia.com/cases/federal/us/592/261/","sc":1,"by":{"1":"15"},"q":[{"src":"brief","b":1,"text":"documents generated during an agency’s deliberations,","cite":"592 U.S. 261, 263"}]},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"render[] superfluous another portion of that same law.","cite":"564 U.S. 162, 185"}]},{"t":"case","label":"Wachovia Bank v. Schmidt","cite":"546 U.S. 303","y":2006,"id":"2005/04-1186","sc":1,"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"depends on the context in and purpose for which it is used.","cite":"546 U.S. 303, 318"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"depends on the context in and purpose for which it is used.","cite":"546 U. S. 303, 318"}]},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"1":"35"}},{"t":"law","label":"Pub. L. No. 102-190","url":"https://www.govinfo.gov/link/statute/105/1380","by":{"1":"4"}},{"t":"law","label":"Pub. L. No. 112-81","url":"https://www.govinfo.gov/link/plaw/112/public/81","by":{"1":"4"}},{"t":"law","label":"Pub. L. No. 112-239","url":"https://www.govinfo.gov/link/plaw/112/public/239","by":{"1":"5"}},{"t":"usc","label":"50 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/50/1601","by":{"1":"18"}},{"t":"usc","label":"50 U.S.C. § 1701","url":"https://www.law.cornell.edu/uscode/text/50/1701","subs":["(a)"],"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"to the national security, foreign policy, or economy of the United States.","cite":"50 U.S.C. 1701(a)"}]},{"t":"usc","label":"50 U.S.C. § 1702","url":"https://www.law.cornell.edu/uscode/text/50/1702","by":{"1":"18"}},{"t":"law","label":"Pub. L. No. 111-8","url":"https://www.govinfo.gov/link/plaw/111/public/8","by":{"1":"5"}},{"t":"usc","label":"5 U.S.C. § 7701","url":"https://www.law.cornell.edu/uscode/text/5/7701","subs":["(e)(1)"],"by":{"1":"9"}},{"t":"usc","label":"10 U.S.C. § 129d","url":"https://www.law.cornell.edu/uscode/text/10/129d","subs":["(a)(1)"],"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"the disclosure is for the sole purpose of providing litigation support to the Government * * * during or in anticipation of litigation.","cite":"10 U.S.C. 129d(a)(1)"}]},{"t":"usc","label":"10 U.S.C. § 427","url":"https://www.law.cornell.edu/uscode/text/10/427","subs":["(g)(1)"],"stext":{"head":"§427. Conflict Records Research Center","paras":[[0,"(a) Center Authorized.—The Secretary of Defense may establish a center to be known as the \"Conflict Records Research Center\" (in this section referred to as the \"Center\")."],[0,"(b) Purposes.—The purposes of the Center shall be the following:"],[1,"(1) To establish a digital research database, including translations, and to facilitate research and analysis of records captured from countries, organizations, and individuals, now or once hostile to the United States, with rigid adherence to academic freedom and integrity."],[1,"(2) Consistent with the protection of national security information, personally identifiable information, and intelligence sources and methods, to make a significant portion of these records available to researchers as quickly and responsibly as possible while taking into account the integrity of the academic process and risks to innocents or third parties."],[1,"(3) To conduct and disseminate research and analysis to increase the understanding of factors related to international relations, counterterrorism, and conventional and unconventional warfare and, ultimately, enhance national security."],[1,"(4) To collaborate with members of academic and broad national security communities, both domestic and international, on research, conferences, seminars, and other information exchanges to identify topics of importance for the leadership of the United States Government and the scholarly community."],[0,"(c) Concurrence of the Director of National Intelligence.—The Secretary of Defense shall seek the concurrence of the Director of National Intelligence to the extent the efforts and activities of the Center involve the entities referred to in subsection (b)(4)."],[0,"(d) Support From Other United States Government Departments or Agencies.—The head of any non-Department of Defense department or agency of the United States Government may—"],[1,"(1) provide to the Secretary of Defense services, including personnel support, to support the operations of the Center; and"],[1,"(2) transfer funds to the Secretary of Defense to support the operations of the Center."],[0,"(e) Acceptance of Gifts and Donations.—(1) Subject to paragraph (3), the Secretary of Defense may accept from any source specified in paragraph (2) any gift or donation for purposes of defraying the costs or enhancing the operations of the Center."],[0,"(2) The sources specified in this paragraph are the following:"],[1,"(A) The government of a State or a political subdivision of a State."],[1,"(B) The government of a foreign country."],[1,"(C) A foundation or other charitable organization, including a foundation or charitable organization that is organized or operates under the laws of a foreign country."],[1,"(D) Any source in the private sector of the United States or a foreign country."],[0,"(3) The Secretary may not accept a gift or donation under this subsection if acceptance of the gift or donation would compromise or appear to compromise—"],[1,"(A) the ability of the Department of Defense, any employee of the Department, or any member of the armed forces to carry out the responsibility or duty of the Department in a fair and objective manner; or"],[1,"(B) the integrity of any program of the Department or of any person involved in such a program."],[0,"(4) The Secretary shall provide written guidance setting forth the criteria to be used in determining the applicability of paragraph (3) to any proposed gift or donation under this subsection."],[0,"(f) Crediting of Funds Transferred or Accepted.—Funds transferred to or accepted by the Secretary of Defense under this section shall be credited to appropriations available to the Department of Defense for the Center, and shall be available for the same purposes, and subject to the same conditions and limitations, as the appropriations with which merged. Any funds so transferred or accepted shall remain available until expended."],[0,"(g) Definitions.—In this section:"],[1,"(1) The term \"captured record\" means a document, audio file, video file, or other material captured during combat operations from countries, organizations, or individuals, now or once hostile to the United States."],[1,"(2) The term \"gift or donation\" means any gift or donation of funds, materials (including research materials), real or personal property, or services (including lecture services and faculty services)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/427?type=usc&year=mostrecent&link-type=html"},"by":{"1":"16"},"q":[{"src":"brief","b":1,"text":"captured during combat operations from countries, organizations, or individuals, now or once hostile to the United States.","cite":"10 U.S.C. 427(g)(1)"}]},{"t":"usc","label":"10 U.S.C. § 802","url":"https://www.law.cornell.edu/uscode/text/10/802","subs":["(d)"],"by":{"1":"22"}},{"t":"usc","label":"10 U.S.C. § 1074m","url":"https://www.law.cornell.edu/uscode/text/10/1074m","subs":["(a)"],"by":{"1":"5"}},{"t":"usc","label":"10 U.S.C. § 1145","url":"https://www.law.cornell.edu/uscode/text/10/1145","subs":["(a)(2)(C)","(a)(2)(D)"],"by":{"1":"5, 5"}},{"t":"usc","label":"10 U.S.C. § 2229","url":"https://www.law.cornell.edu/uscode/text/10/2229","subs":["(b)(2)"],"by":{"1":"5, 22"}},{"t":"usc","label":"10 U.S.C. § 2347","url":"https://www.law.cornell.edu/uscode/text/10/2347","subs":["(c)"],"by":{"1":"5"}},{"t":"usc","label":"10 U.S.C. § 2662","url":"https://www.law.cornell.edu/uscode/text/10/2662","by":{"1":"22, 5, 22"}},{"t":"usc","label":"10 U.S.C. § 4862","url":"https://www.law.cornell.edu/uscode/text/10/4862","subs":["(d)(1)"],"by":{"1":"22"}},{"t":"usc","label":"10 U.S.C. § 4863","url":"https://www.law.cornell.edu/uscode/text/10/4863","subs":["(c)(1)"],"by":{"1":"5"}},{"t":"usc","label":"10 U.S.C. § 10147","url":"https://www.law.cornell.edu/uscode/text/10/10147","subs":["(a)(1)","(a)(2)"],"by":{"1":"23, 23"}},{"t":"usc","label":"10 U.S.C. § 12301","url":"https://www.law.cornell.edu/uscode/text/10/12301","subs":["(d)"],"by":{"1":"7"}},{"t":"usc","label":"10 U.S.C. § 12302","url":"https://www.law.cornell.edu/uscode/text/10/12302","by":{"1":"7"},"q":[{"src":"argument","who":"Mr. Tutt","text":"Feliciano was called to active duty under Section 12302 orders to do the exact same duties that he had performed under his 12301(d) orders."}]},{"t":"usc","label":"10 U.S.C. § 12304a","url":"https://www.law.cornell.edu/uscode/text/10/12304a","subs":["(a)"],"by":{"1":"4, 20"},"q":[{"src":"brief","b":1,"text":"[w]hen a Governor requests Federal assistance in responding to a major disaster or emergency,","cite":"10 U.S.C. 12304a(a)"}]},{"t":"usc","label":"10 U.S.C. § 12304b","url":"https://www.law.cornell.edu/uscode/text/10/12304b","by":{"1":"6, 21"}},{"t":"usc","label":"10 U.S.C. § 16163","url":"https://www.law.cornell.edu/uscode/text/10/16163","subs":["(a)(1)"],"by":{"1":"5"}},{"t":"usc","label":"14 U.S.C. § 712","url":"https://www.law.cornell.edu/uscode/text/14/712","subs":["(2012)"],"by":{"1":"5"}},{"t":"usc","label":"14 U.S.C. § 1109","url":"https://www.law.cornell.edu/uscode/text/14/1109","subs":["(c)(3)(A)"],"by":{"1":"5, 22"}},{"t":"usc","label":"14 U.S.C. § 3713","url":"https://www.law.cornell.edu/uscode/text/14/3713","stext":{"head":"§3713. Active duty for emergency augmentation of regular forces","paras":[[0,"(a) Notwithstanding another law, and for the emergency augmentation of the Regular Coast Guard forces during a, or to aid in prevention of an imminent, serious natural or manmade disaster, accident, catastrophe, act of terrorism (as defined in section 2 of the Homeland Security Act of 2002 (6 U.S.C. 101)), or transportation security incident as defined in section 70101 of title 46, the Secretary may, without the consent of the member affected, order to active duty of not more than 120 days in any 2-year period an organized training unit of the Coast Guard Ready Reserve, a member thereof, or a member not assigned to a unit organized to serve as a unit."],[0,"(b) Under the circumstances of the domestic emergency involved, a reasonable time shall be allowed between the date when a Reserve member ordered to active duty under this section is alerted for that duty and the date when the member is required to enter upon that duty. Unless the Secretary determines that the nature of the domestic emergency does not allow it, this period shall be at least two days."],[0,"(c) Active duty served under this section—"],[1,"(1) satisfies on a day-for-day basis all or a part of the annual active duty for training requirement of section 10147 of title 10;"],[1,"(2) does not satisfy any part of the active duty obligation of a member whose statutory Reserve obligation is not already terminated; and"],[1,"(3) entitles a member while engaged therein, or while engaged in authorized travel to or from that duty, to all rights and benefits, including pay and allowances and time creditable for pay and retirement purposes, to which the member would be entitled while performing other active duty."],[0,"(d) Reserve members ordered to active duty under this section shall not be counted in computing authorized strength of members on active duty or members in grade under this title or under any other law."],[0,"(e) For purposes of calculating the duration of active duty allowed pursuant to subsection (a), each period of active duty shall begin on the first day that a member reports to active duty, including for purposes of training."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/14/3713?type=usc&year=mostrecent&link-type=html"},"by":{"1":"5, 20","2":"14, 16"}},{"t":"usc","label":"18 U.S.C. § 844","url":"https://www.law.cornell.edu/uscode/text/18/844","subs":["(h)(2)"],"by":{"1":"14, 26, 27"}},{"t":"usc","label":"22 U.S.C. § 2421f","url":"https://www.law.cornell.edu/uscode/text/22/2421f","subs":["(e)(3)"],"by":{"1":"5"}},{"t":"usc","label":"33 U.S.C. § 467b","url":"https://www.law.cornell.edu/uscode/text/33/467b","by":{"1":"16"}},{"t":"usc","label":"37 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/37/101","subs":["(18)","(19)"],"by":{"1":"5, 5"}},{"t":"usc","label":"38 U.S.C. § 4303","url":"https://www.law.cornell.edu/uscode/text/38/4303","subs":["(13)"],"by":{"1":"5"},"q":[{"src":"brief","b":1,"text":"active duty, active duty for training, * * * inactive duty training, [and] full-time National Guard duty,","cite":"38 U.S.C. 4303(13)"}]},{"t":"usc","label":"41 U.S.C. § 2312","url":"https://www.law.cornell.edu/uscode/text/41/2312","subs":["(d)(1)"],"by":{"1":"5"}},{"t":"usc","label":"42 U.S.C. § 9703","url":"https://www.law.cornell.edu/uscode/text/42/9703","subs":["(a)(2)"],"by":{"1":"16"}},{"t":"usc","label":"46 U.S.C. § 51901","url":"https://www.law.cornell.edu/uscode/text/46/51901","subs":["(b)(3)"],"by":{"1":"31"}},{"t":"usc","label":"49 U.S.C. § 40122","url":"https://www.law.cornell.edu/uscode/text/49/40122","subs":["(g)(2)"],"by":{"1":"3"}},{"t":"reg","label":"3 C.F.R. pt. 231","url":"https://www.ecfr.gov/current/title-3/part-231","by":{"1":"18"}},{"t":"reg","label":"Blocking Property of Certain Persons Contributing to the Situation in Nicaragua, Exec. Order No. 13,851, 83 Fed. Reg. 61,505","url":"https://www.govinfo.gov/link/fr/83/61505","by":{"1":"18"}},{"t":"reg","label":"Blocking Property With Respect to the Situation in Burma, Exec. Order No. 14,014, 86 Fed. Reg. 9429","url":"https://www.govinfo.gov/link/fr/86/9429","by":{"1":"18"}},{"t":"reg","label":"Continuation of Emergency Regarding Export Control Regulations, 56 Fed. Reg. 49,385","url":"https://www.govinfo.gov/link/fr/56/49385","by":{"1":"19"}},{"t":"reg","label":"Continuation of Iran Emergency, 56 Fed. Reg. 57,791","url":"https://www.govinfo.gov/link/fr/56/57791","by":{"1":"19"}},{"t":"reg","label":"Continuation of Libyan Emergency, 56 Fed. Reg. 477","url":"https://www.govinfo.gov/link/fr/56/477","by":{"1":"19"}},{"t":"reg","label":"Continuation of the National Emergency With Respect to Iran, 88 Fed. Reg. 77,489","url":"https://www.govinfo.gov/link/fr/88/77489","by":{"1":"18"}},{"t":"reg","label":"Declaring a National Emergency Concerning the Novel Coronavirus Disease (COVID–19) Outbreak, Proclamation No. 9994, 85 Fed. Reg. 15,337","url":"https://www.govinfo.gov/link/fr/85/15337","by":{"1":"24"}},{"t":"reg","label":"Prohibiting Certain Transactions With Respect to Haiti, 56 Fed. Reg. 50,641","url":"https://www.govinfo.gov/link/fr/56/50641","by":{"1":"6, 19"}},{"t":"case","label":"Atl. Richfield Co. v. Christian","cite":"590 U.S. 1","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/1/","sc":1,"by":{"2":"16"},"q":[{"src":"brief","b":2,"text":"employed a belt and suspenders approach","cite":"590 U.S. 1, 14 n.5"}]},{"t":"case","label":"Marvin M. Brandt Revocable Trust v. United States","cite":"572 U.S. 93","y":2014,"id":"2013/12-1173","sc":1,"by":{"2":"15"}},{"t":"case","label":"United States v. Price","cite":"351 U.S. 304","y":1960,"id":"1959/48","sc":1,"by":{"2":"15"},"q":[{"src":"brief","b":2,"text":"the views of a subsequent Congress form a hazardous basis for inferring the intent of an earlier one","cite":"351 U.S. 304, 313"}]},{"t":"usc","label":"18 U.S.C. § 209","url":"https://www.law.cornell.edu/uscode/text/18/209","subs":["(h)"],"stext":{"head":"§209. Salary of Government officials and employees payable only by United States","paras":[[0,"(a) Whoever receives any salary, or any contribution to or supplementation of salary, as compensation for his services as an officer or employee of the executive branch of the United States Government, of any independent agency of the United States, or of the District of Columbia, from any source other than the Government of the United States, except as may be contributed out of the treasury of any State, county, or municipality; or"],[0,"Whoever, whether an individual, partnership, association, corporation, or other organization pays, makes any contribution to, or in any way supplements, the salary of any such officer or employee under circumstances which would make its receipt a violation of this subsection—"],[0,"Shall be subject to the penalties set forth in section 216 of this title."],[0,"(b) Nothing herein prevents an officer or employee of the executive branch of the United States Government, or of any independent agency of the United States, or of the District of Columbia, from continuing to participate in a bona fide pension, retirement, group life, health or accident insurance, profit-sharing, stock bonus, or other employee welfare or benefit plan maintained by a former employer."],[0,"(c) This section does not apply to a special Government employee or to an officer or employee of the Government serving without compensation, whether or not he is a special Government employee, or to any person paying, contributing to, or supplementing his salary as such."],[0,"(d) This section does not prohibit payment or acceptance of contributions, awards, or other expenses under the terms of chapter 41 of title 5."],[0,"(e) This section does not prohibit the payment of actual relocation expenses incident to participation, or the acceptance of same by a participant in an executive exchange or fellowship program in an executive agency: Provided, That such program has been established by statute or Executive order of the President, offers appointments not to exceed three hundred and sixty-five days, and permits no extensions in excess of ninety additional days or, in the case of participants in overseas assignments, in excess of three hundred and sixty-five days."],[0,"(f) This section does not prohibit acceptance or receipt, by any officer or employee injured during the commission of an offense described in section 351 or 1751 of this title, of contributions or payments from an organization which is described in section 501(c)(3) of the Internal Revenue Code of 1986 and which is exempt from taxation under section 501(a) of such Code."],[0,"(g)(1) This section does not prohibit an employee of a private sector organization, while assigned to an agency under chapter 37 of title 5, from continuing to receive pay and benefits from such organization in accordance with such chapter."],[0,"(2) For purposes of this subsection, the term \"agency\" means an agency (as defined by section 3701 of title 5) and the Office of the Chief Technology Officer of the District of Columbia."],[0,"(h) This section does not prohibit a member of the reserve components of the armed forces, or a member of the Space Force, on active duty pursuant to a call or order to active duty under a provision of law referred to in section 101(a)(13) of title 10 from receiving from any person that employed such member before the call or order to active duty any payment of any part of the salary or wages that such person would have paid the member if the member's employment had not been interrupted by such call or order to active duty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/209?type=usc&year=mostrecent&link-type=html"},"by":{"2":"10, 11"},"q":[{"src":"argument","who":"Mr. Tutt","text":"Section 209 if they get the question wrong. The government has yet to offer any theory for how to assess whether a reservist's service is in the course of a national emergency, other than saying courts should defer to the government's own characterization in a reservist's orders."},{"src":"argument","who":"Justice Gorsuch","text":"Reaves, in response to Justice Thomas's question about the criminal liability under Section 209, I -- I -- I take the mens rea point on past liability, but I -- I -- I think your friend on the other side had a -- a stronger point that I didn't hear you address, and that is private employers will have no way ex ante to know whether they're violating a federal felony -- committing a federal felony because they don't have access to orders all the time."}]},{"t":"reg","label":"Authority to Hold Harmless and Indemnify in Certain Circumstances Under One Contract, 68 Fed. Reg. 19,705","url":"https://www.govinfo.gov/link/fr/68/19705","by":{"2":"7"}},{"t":"reg","label":"Authorizing the Exercise of Authority Under Public Law 85-804, 79 Fed. Reg. 68,757","url":"https://www.govinfo.gov/link/fr/79/68757","by":{"2":"7"}}]};